import Transport from 'winston-transport';

interface Clock {
    now(): number;
}

declare class Diagnostics {
    private readonly enabled;
    private readonly write;
    private readonly secrets;
    private count;
    constructor(enabled: boolean, write: (line: string) => void, secrets: readonly string[]);
    record(error: unknown): void;
    warn(message: string): void;
    get errorCount(): number;
    private describe;
    private redact;
}

interface LogSource {
    readonly name: string;
    install(): void;
    dispose(): void;
}

interface EventContext {
    service: string;
    environment: string;
    release?: string;
    traceId?: string;
    spanId?: string;
    parentSpanId?: string;
}

type Kind = 'log' | 'error' | 'trace' | 'span' | 'metric';
interface TelemetryEvent {
    kind: Kind;
    timestamp: number;
    context: EventContext;
}

interface Sink {
    emit(event: TelemetryEvent): void;
}

declare abstract class BaseLogSource implements LogSource {
    protected readonly sink: Sink;
    protected readonly clock: Clock;
    protected readonly service: string;
    protected readonly environment: string;
    protected readonly diagnostics: Diagnostics;
    abstract readonly name: string;
    private installed;
    constructor(sink: Sink, clock: Clock, service: string, environment: string, diagnostics: Diagnostics);
    install(): void;
    dispose(): void;
    protected isInstalled(): boolean;
    protected abstract doInstall(): void;
    protected abstract doDispose(): void;
}

declare class PinoSource extends BaseLogSource {
    readonly name = "pino";
    write(chunk: string): void;
    protected doInstall(): void;
    protected doDispose(): void;
}

type WinstonSource = Transport & LogSource & {
    log(info: Record<string, unknown>, callback: () => void): void;
};

interface SdkMeta {
    name: string;
    version: string;
}

declare class Batcher {
    private readonly maxBatchSize;
    private readonly flushIntervalMs;
    private readonly onFlush;
    private pending;
    private stopped;
    private timer;
    constructor(maxBatchSize: number, flushIntervalMs: number, onFlush: () => void);
    add(): void;
    clear(): void;
    stop(): void;
    private fire;
}

type CircuitBreakerState = 'closed' | 'open' | 'half-open';

declare class CircuitBreaker {
    private readonly clock;
    private readonly failureThreshold;
    private readonly cooldownMs;
    private state;
    private failureCount;
    private openedAt;
    constructor(clock: Clock, failureThreshold: number, cooldownMs: number);
    get currentState(): CircuitBreakerState;
    isOpen(): boolean;
    recordSuccess(): void;
    recordFailure(): void;
    private trip;
}

interface Envelope {
    sentAt: number;
    sdk: SdkMeta;
    events: TelemetryEvent[];
}

interface ExportPayload {
    body: Buffer;
    contentEncoding: string;
}

declare class Compressor {
    compress(envelope: Envelope): Promise<ExportPayload>;
}

declare class EventQueue {
    private readonly maxQueueSize;
    private readonly events;
    private dropped;
    constructor(maxQueueSize: number);
    enqueue(event: TelemetryEvent): void;
    dequeueBatch(max: number): TelemetryEvent[];
    get size(): number;
    get droppedCount(): number;
    get isEmpty(): boolean;
    requeueFront(events: TelemetryEvent[]): void;
}

interface ExportResult {
    ok: boolean;
}
interface Exporter {
    export(payload: ExportPayload): Promise<ExportResult>;
}

interface Randomness {
    next(): number;
    bytes(count: number): Buffer;
}

declare class RetryPolicy {
    private readonly randomness;
    private readonly baseDelayMs;
    private readonly maxDelayMs;
    private readonly maxAttempts;
    constructor(randomness: Randomness, baseDelayMs: number, maxDelayMs: number, maxAttempts: number);
    shouldRetry(attempt: number): boolean;
    delayMs(attempt: number): number;
}

declare class Dispatcher {
    private readonly queue;
    private readonly compressor;
    private readonly exporter;
    private readonly clock;
    private readonly meta;
    private readonly maxBatchSize;
    private readonly retryPolicy;
    private readonly breaker;
    private readonly diagnostics;
    private batcher;
    private chain;
    constructor(queue: EventQueue, compressor: Compressor, exporter: Exporter, clock: Clock, meta: SdkMeta, maxBatchSize: number, retryPolicy: RetryPolicy, breaker: CircuitBreaker, diagnostics: Diagnostics);
    bindBatcher(batcher: Batcher): void;
    enqueue(event: TelemetryEvent): void;
    flushBatch(): Promise<void>;
    flush(): Promise<void>;
    drainForShutdown(): Promise<void>;
    private serialize;
    private drainAll;
    private drainBatch;
}

interface ProcessSignals {
    add(signal: NodeJS.Signals, handler: () => void): void;
    remove(signal: NodeJS.Signals, handler: () => void): void;
}

declare class Lifecycle {
    private readonly signals;
    private readonly registrar;
    private readonly flush;
    private readonly timeoutMs;
    private readonly stopAccepting;
    private readonly stopProcessing;
    private readonly diagnostics;
    private pending;
    private readonly onSignal;
    constructor(signals: NodeJS.Signals[], registrar: ProcessSignals, flush: () => Promise<void>, timeoutMs: number, stopAccepting: () => void, stopProcessing: () => void, diagnostics: Diagnostics);
    install(): void;
    shutdown(): Promise<void>;
    private run;
    private drain;
    private boundedDrain;
}

interface Processor {
    process(event: TelemetryEvent): TelemetryEvent | null;
}

declare class Pipeline {
    private readonly processors;
    constructor(processors: Processor[]);
    run(event: TelemetryEvent): TelemetryEvent | null;
}

declare class Sdk implements Sink {
    private readonly pipeline;
    private readonly dispatcher;
    private readonly diagnostics;
    private readonly clock;
    private readonly context;
    private lifecycle;
    private pinoSource;
    private winstonSource;
    constructor(pipeline: Pipeline, dispatcher: Dispatcher, diagnostics: Diagnostics, clock: Clock, context: EventContext);
    bindLifecycle(lifecycle: Lifecycle): void;
    bindSources(pinoSource: PinoSource | undefined, winstonSource: WinstonSource | undefined): void;
    getPinoDestination(): PinoSource | undefined;
    getWinstonTransport(): WinstonSource | undefined;
    captureException(error: unknown): void;
    emit(event: TelemetryEvent): void;
    deliver(): Promise<void>;
    shutdown(): Promise<void>;
}

export { Sdk as S };
